function countPendingAfterNodeFailure(nodes, pods, failedNodeName) {
  const initial = scheduleSpread(nodes, pods);
  const lostPods = initial.placements
    .filter((p) => p.node === failedNodeName)
    .map((pl) => pods.find((p) => p.name === pl.pod));
  const survivors = initial.remaining.filter((n) => n.name !== failedNodeName);
  const reconciled = scheduleSpread(survivors, lostPods);
  return reconciled.pending.length;
}
